{
  "groups": [
    {
      "group_id": "low_rate_fixed_rate_vulnerability",
      "rule": "rate_type == 'fixed' and origination_year <= 2021.0 and mortgage_rate_pct < 4.0",
      "rationale": "Borrowers who locked in historic low fixed rates face the most severe payment shock upon renewal and are highly likely to shop for better rates."
    },
    {
      "group_id": "highly_leveraged_uninsured_owners",
      "rule": "insured_flag == False and credit_utilization_pct > 50.0 and mortgage_balance_cad > 400000.0",
      "rationale": "Uninsured borrowers with high debt loads and significant outstanding balances have limited equity and face higher hurdles to refinance with other lenders."
    },
    {
      "group_id": "financially_constrained_families",
      "rule": "n_children >= 2 and household_income_cad < 75000.0 and has_savings == False",
      "rationale": "Households with multiple children and low liquidity have the least budget slack to absorb rising monthly costs and are susceptible to delinquency."
    },
    {
      "group_id": "prime_equity_rich_leavers",
      "rule": "credit_score_band == '720_plus' and mortgage_balance_cad < 350000.0 and has_investments == True",
      "rationale": "Financially stable borrowers with high credit scores and low relative debt have the greatest mobility and may easily switch lenders for lower rates."
    },
    {
      "group_id": "variable_rate_shock_segment",
      "rule": "rate_type == 'variable' and payment_structure == 'adjustable_payment' and mortgage_rate_pct >= 5.0",
      "rationale": "Variable rate borrowers with adjustable payments have already seen their cash flow tighten significantly and may require proactive engagement to prevent attrition."
    },
    {
      "group_id": "credit_risk_captive_borrowers",
      "rule": "credit_score_band in ['below_600', '600_659'] and insured_flag == True",
      "rationale": "Borrowers with lower credit scores who are insured are often locked into their current lender due to difficulties meeting underwriting standards elsewhere."
    },
    {
      "group_id": "senior_low_income_fixed",
      "rule": "primary_borrower_age >= 65.0 and employment_status == 'retired'",
      "rationale": "Retired borrowers living on fixed incomes are sensitive to payment changes and typically maintain long-term loyalty if they are not pushed to extreme hardship."
    }
  ]
}
